function refuse(reason) {
  return [{ json: { ...input, authorised: false, needs_approval: false, reason, risk: RISK, skill: SKILL } }];
}
if (!session) return refuse('No identified customer in this session. Identification happens before any account action.');

// Validate the inputs before anything runs: a blank account id must not skip the ownership check.
const ACCOUNT_REQUIRED = true;
function invalid() {
  if (ACCOUNT_REQUIRED && !String(input.account_id || '').trim()) return 'An account id is required.';
  const months = input.period_months;
  if (months !== undefined && months !== null && months !== '' &&
      !(Number.isInteger(Number(months)) && Number(months) >= 1 && Number(months) <= 24)) {
    return 'A statement can cover 1 to 24 months.';
  }
  return '';
}
const problem = invalid();
if (problem) return refuse(problem);

if ((ACCOUNT_REQUIRED || input.account_id) && (!owner || owner.customer_id !== session.customer_id)) {
  return refuse('The account does not belong to the identified customer.');
}
const needs_approval = (false);
return [{ json: { ...input, authorised: true, needs_approval, reason: needs_approval ? 'Policy requires a named decision owner to approve before this runs.' : 'Within policy for this customer.', risk: RISK, skill: SKILL, customer: session } }];

const j = $input.first().json;
const months = Number(j.period_months) || 3;
const end = new Date();
const start = new Date(end); start.setMonth(start.getMonth() - months);
