return [{ json: { ...j, status: 'done', result: `Statement printed for ${j.account_id} covering ${fmt(start)} to ${fmt(end)} (${months} months). Stamped copy handed to the customer at the concierge desk. Reference STM-${Date.now().toString().slice(-6)}.` } }];
